<script setup lang="ts">
// SiteFooter: reusable Avada footer. Structure and link menus are shared;
// the Cloudflare email-protection hash is the only per-page difference.
const props = withDefaults(defineProps<{ emailHash?: string }>(), { emailHash: 'c6b5a7aaa3b586a7aaaab3b0afa5a7b4a3e8a5a9ab' })

function decodeCfEmail(h) {
  let r = parseInt(h.slice(0, 2), 16), o = h.slice(2), s = ''
  for (let i = 0; i < o.length; i += 2) s += String.fromCharCode(parseInt(o.slice(i, i + 2), 16) ^ r)
  return s
}
function initEmail() {
  if (typeof window === 'undefined') return
  const hash = props.emailHash
  if (!hash || !/^[a-f0-9]+$/i.test(hash)) return
  const mail = decodeCfEmail(hash)
  document.querySelectorAll('a[href*=\'/cdn-cgi/l/email-protection\']').forEach((a) => {
    a.href = 'mailto:' + mail
    a.textContent = mail
  })
}
